        String prefix = ModuleUtils.getInstance().getModuleConfig(request, application)
                .getPrefix();
        return (ValidatorResources) application.getAttribute(ValidatorPlugIn.VALIDATOR_KEY
                + prefix);
    }

    public static MessageResources getMessageResources(
        HttpServletRequest request) {
        return (MessageResources) request.getAttribute(Globals.MESSAGES_KEY);
    }

    public static MessageResources getMessageResources(
        ServletContext application, HttpServletRequest request, String bundle) {
        MessageResources messages = (MessageResources) request.getAttribute(bundle);
        if (messages == null) {
            ModuleConfig moduleConfig = ModuleUtils.getInstance()
                .getModuleConfig(request, application);
            messages = (MessageResources) application.getAttribute(bundle
                    + moduleConfig.getPrefix());
        }
        if (messages == null) {
            messages = (MessageResources) application.getAttribute(bundle);
        }
        return messages;
    }

    public static String getVarValue(String varName, Field field, Validator validator,
        HttpServletRequest request, boolean required) {
        Var var = field.getVar(varName);
        if (var == null) {
            String msg = sysmsgs.getMessage("variable.missing", varName);
            if (required) {
                throw new IllegalArgumentException(msg);
            }
            return null;
        }
        ServletContext application = (ServletContext) validator.getParameterValue(
            SERVLET_CONTEXT_PARAM);
        return getVarValue(var, application, request, required);
    }

    private static String getVarValue(Var var, ServletContext application,
        HttpServletRequest request, boolean required) {
        String varName = var.getName();
        String varValue = var.getValue();
        if (!var.isResource()) {
            return varValue;
        }
        String bundle = var.getBundle();
        MessageResources messages = getMessageResources(application, request, bundle);
        Locale locale = RequestUtils.getUserLocale(request);
        String value = messages.getMessage(locale, varName, null);
        if (value == null && required) {
            throw new IllegalArgumentException(sysmsgs.getMessage(
                    "variable.resource.notfound", varName, varValue, bundle));
        }
        return value;
