    internal class TrueTypeFontUnicode : TrueTypeFont, IComparer {
        private bool vertical = false;

        internal TrueTypeFontUnicode(string ttFile, string enc, bool emb, byte[] ttfAfm) {
            string nameBase = GetBaseName(ttFile);
            string ttcName = GetTTCName(nameBase);
            if (nameBase.Length < ttFile.Length) {
                style = ttFile.Substring(nameBase.Length);
            }
            encoding = enc;
            embedded = emb;
            fileName = ttcName;
            ttfIndex = "";
            if (ttcName.Length < nameBase.Length) {
                ttfIndex = nameBase.Substring(ttcName.Length);
            }
            FontType = FONT_TYPE_TTUNI;
            if ((fileName.ToLower().EndsWith(".ttf") || fileName.ToLower().EndsWith(".otf") || fileName.ToLower().EndsWith(".ttc")) && (enc.Equals(IDENTITY_H || enc.Equals(IDENTITY_V))) && embedded) {
                Process(ttfAfm);
                if (os_2.fsType == 2) {
                    throw new DocumentException(fileName + style + " cannot be embedded due to licensing restrictions.");
                }
                // Sivan
                if ((cmap31 == null && !fontSpecific) || (cmap10 == null && fontSpecific)) {
                    directTextToByte = true;
                }
                // Throw if cmap31 or cmap10 is null
                if (fontSpecific) {
                    fontSpecific = false;
                    String tempEncoding = encoding;
                    encoding = "";
                    CreateEncoding();
                    encoding = tempEncoding;
                }
            } else {
                throw new DocumentException(fileName + style + " is not a TTF font file.");
            }
            vertical = enc.EndsWith("V");
        }

        public override int Compare(object o1, object o2) {
            int result = 0;
            if (o1 != null && o2 != null) {
                int m1 = ((int)o1)[0];
                int m2 = ((int)o2)[0];
                if (m1 < m2) {
                    result = -1;
                } else if (m1 > m2) {
                    result = 1;
                } else {
                    result = 0;
                }
            }
            return result;
        }

        private void Process(byte[] ttfAfm) {
            // Process the TTF file data
        }

        private string GetBaseName(string ttFile) {
            return ttFile.Substring(0, ttFile.Length - 1);
        }

        private string GetTTCName(string nameBase) {
            return nameBase.Substring(1);
        }

