using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Threading;
using System.Windows.Forms;
using CANAPE.Controls;
using CANAPE.Nodes;
using CANAPE.Utils;

namespace CANAPE.Forms
{
    partial class PacketLogViewerForm
    {
        private int _index;
        private IList<LogPacket> _packets;
        private PacketEntry[] _modifiedPackets;
        private bool _newStyleLogViewer;
        private struct PacketEntry
        {
            public bool modified;
            public LogPacket packet;
        }

        public PacketLogViewerForm(LogPacket curr, IList<LogPacket> packets)
        {
            InitializeComponent();
            _index = -1;
            _packets = packets;
            _modifiedPackets = new PacketEntry[_packets.Count];
            _newStyleLogViewer = GlobalControlConfig.NewStyleLogViewer;

            if (packets.Count > 0)
            {
                _index = 0;
                _modifiedPackets[_index].modified = false;
                _modifiedPackets[_index].packet = packets[_index].Clone();
            }

            timer.Start();
        }

        private void SetModifiedFrame()
        {
            _modifiedPackets[_index].modified = false;
            _modifiedPackets[_index].packet = packets[_index].Clone();
        }

        private void UpdatePacketDisplay()
        {
            LogPacket p = GetCurrentPacket();
            if (p == null)
            {
                return;
            }

            if (!_newStyleLogViewer)
            {
                frameEditorControl.ReadOnly = ReadOnly;
            }

            frameEditorControl.SetFrame(p.Frame, null, ColorValueConverter.ToColor(p.Color));
            if (p.Frame.IsBasic || (ReadOnly && !_newStyleLogViewer))
            {
                toolStripButtonConvertToBytes.Enabled = false;
            }
            else
            {
                toolStripButtonConvertToBytes.Enabled = true;
            }

            toolStripLabelPosition.Text = String.Format(CANAPE.Properties.Resources.PacketLogViewerForm.Header, _index + 1, packets.Count, p.Tag, p.Network, p.Timestamp.ToString());
        }

        private LogPacket GetCurrentPacket()
        {
            if (_packets.Count == 0)
            {
                return null;
            }

            if (_newStyleLogViewer)
            {
                if (_modifiedPackets[_index].packet == null)
                {
                    SetModifiedFrame();
                }
                return _modifiedPackets[_index].packet;
            }
            else
            {
                return _packets[_index];
            }
        }

        private void OnFrameModified()
        {
            SetModifiedFrame();
            toolStripButtonSave.Enabled = (IsFrameModified());
            toolStripButtonRevert.Enabled = (IsFrameModified());
        }

        private void timer_Tick(object sender, EventArgs e)
        {
            if (_packets.Count == 0)
            {
                return;
            }

            if (_modifiedPackets[_index].modified)
            {
                _modifiedPackets[_index].modified = false;
                _modifiedPackets[_index].packet = packets[_index].Clone();
            }
        }

        private void _currPacket_FrameModified(object sender, EventArgs e)
        {
            if (InvokeRequired)
            {
                Invoke(new Action(OnFrameModified));
            }
            else
            {
                OnFrameModified();
            }
        }

        private void toolStripButtonForward_Click(object sender, EventArgs e)
        {
            _index++;
            if (_index > _packets.Count - 1)
            {
                _index = 0;
            }
            UpdatePacketDisplay();
        }

        private void toolStripButtonBack_Click(object sender, EventArgs e)
        {
            _index--;
            if (_index < 0)
            {
                _index = _packets.Count - 1;
            }
            UpdatePacketDisplay();
        }

        private void toolStripButtonCopy_Click(object sender, EventArgs e)
        {
            LogPacket curr = GetCurrentPacket();
            if (curr == null)
            {
                return;
            }
            Clipboard.SetText(curr.ToString());
        }

        private void toolStripButtonSave_Click(object sender, EventArgs e)
        {
            if (IsFrameModified())
            {
                toolStripButtonRevert.Enabled = true;
                toolStripButtonConvertToBytes.Enabled = true;
            }
            else
            {
                toolStripButtonRevert.Enabled = false;
                toolStripButtonConvertToBytes.Enabled = false;
            }
        }

        private void toolStripButtonRevert_Click(object sender, EventArgs e)
        {
            _modifiedPackets[_index].modified = true;
            _modifiedPackets[_index].packet = packets[_index].Clone();
            SetModifiedFrame();
        }

        private void toolStripButtonConvertToBytes_Click(object sender, EventArgs e)
        {
            if (IsFrameModified())
            {
                toolStripButtonSave.Enabled = true;
                toolStripButtonRevert.Enabled = true;
            }
            else
            {
                toolStripButtonSave.Enabled = false;
                toolStripButtonRevert.Enabled = false;
            }
        }

        private void toolStripLabelPosition_Click(object sender, EventArgs e)
        {
            toolStripLabelPosition.Text = String.Format(CANAPE.Properties.Resources.PacketLogViewerForm.Header, _index + 1, packets.Count, Tag, Network, Timestamp.ToString());
        }

        private void InitializeComponent()
        {
            // Initialize controls
            toolStripButtonForward = new ToolStripButton();
            toolStripButtonBack = new ToolStripButton();
            toolStripButtonSave = new ToolStripButton();
            toolStripButtonRevert = new ToolStripButton();
            toolStripButtonCopy = new ToolStripButton();
            toolStripButtonConvertToBytes = new ToolStripButton();
            toolStripLabelPosition = new ToolStripLabel();
            toolStripButtonForward.Click += toolStripButtonForward_Click;
            toolStripButtonBack.Click += toolStripButtonBack_Click;
            toolStripButtonSave.Click += toolStripButtonSave_Click;
            toolStripButtonRevert.Click += toolStripButtonRevert_Click;
            toolStripButtonCopy.Click += toolStripButtonCopy_Click;
            toolStripButtonConvertToBytes.Click += toolStripButtonConvertToBytes_Click;
            toolStripLabelPosition.Text = "Position: " + _index + " / " + packets.Count;
            toolStripButtonForward.DisplayStyle = ToolStripItemDisplayStyle.Text;
            toolStripButtonBack.DisplayStyle = ToolStripItemDisplayStyle.Text;
            toolStripButtonSave.DisplayStyle = ToolStripItemDisplayStyle.Text;
            toolStripButtonRevert.DisplayStyle = ToolStripItemDisplayStyle.Text;
            toolStripButtonCopy.DisplayStyle = ToolStripItemDisplayStyle.Text;
            toolStripButtonConvertToBytes.DisplayStyle = ToolStripItemDisplayStyle.Text;
            toolStripButtonForward.Image = Image.FromFile(CANAPE.Properties.Resources.PacketLogViewerForm.ImageForward);
            toolStripButtonBack.Image = Image.FromFile(CANAPE.Properties.Resources.PacketLogViewerForm.ImageBack);
            toolStripButtonSave.Image = Image.FromFile(CANAPE.Properties.Resources.PacketLogViewerForm.ImageSave);
            toolStripButtonRevert.Image = Image.FromFile(CANAPE.Properties.Resources.PacketLogViewerForm.ImageRevert);
            toolStripButtonCopy.Image = Image.FromFile(CANAPE.Properties.Resources.PacketLogViewerForm.ImageCopy);
            toolStripButtonConvertToBytes.Image = Image.FromFile(CANAPE.Properties.Resources.PacketLogViewerForm.ImageConvertToBytes);
            toolStripLabelPosition.Image = Image.FromFile(CANAPE.Properties.Resources.PacketLogViewerForm.LabelPosition);
        }

        private void timer_Tick(object sender, EventArgs e)
        {
            if (_packets.Count == 0)
            {
                return;
            }

            if (_modifiedPackets[_index].modified)
            {
                _modifiedPackets[_index].modified = false;
                _modifiedPackets[_index].packet = packets[_index].Clone();
            }
        }

        private void _currPacket_FrameModified(object sender, EventArgs e)
        {
            if (InvokeRequired)
            {
                Invoke(new Action(OnFrameModified));
            }
            else
            {
                OnFrameModified();
            }
        }

