```csharp
using System;
using System.Collections.Generic;

namespace com.espertech.esper.common.@internal.collection
{
    public class RefCountedSet<TK>
    {
        private bool _hasNullEntry;
        private int _nullEntry;
        private readonly IDictionary<TK, int> _refSet;
        private int _numValues;
        private readonly int _nullEntryCount;

        public RefCountedSet()
        {
            _hasNullEntry = false;
            _nullEntry = 0;
            _numValues = 0;
            _refSet = new Dictionary<TK, int>();
            _nullEntryCount = 0;
        }

        public RefCountedSet(
            IDictionary<TK, int> refSet,
            int numValues)
        {
            _refSet = refSet;
            _numValues = numValues;
        }

        private bool AddNull()
        {
            if (!_hasNullEntry)
            {
                _hasNullEntry = true;
                _numValues++;
                _nullEntry++;
                return true;
            }
            _numValues++;
            _nullEntry++;
            return false;
        }

        public bool Add(TK key)
        {
            if (ReferenceEquals(key, null))
            {
                return AddNull();
            }

            int value;
            if (!_refSet.TryGetValue(key, out value))
            {
                _refSet[key] = 1;
                _numValues++;
                return true;
            }

            value++;
            _numValues++;
            _refSet[key] = value;
            return false;
        }

        public bool Remove(TK key)
        {
            if (ReferenceEquals(key, null))
            {
                return RemoveNull();
            }

            int value;
            if (!_refSet.TryGetValue(key, out value))
            {
                return false;
            }

            if (value == 1)
            {
                _refSet.Remove(key);
                _numValues--;
                return true;
            }

            value--;
            _refSet[key] = value;
            _numValues--;
            return false;
        }

        public bool RemoveAll(TK key)
        {
            return _refSet.Remove(key);
        }

        public ICollection<TK> Keys
        {
            get
            {
                if (_hasNullEntry)
                {
                    return new HashSet<TK> { default(TK) };
                }
                return _refSet.Keys;
            }
        }

        public int Count
        {
            get
            {
