def _fbp_filter_op(norm_freq, filter_type, frequency_scaling):
    """Create a FBP filter operator."""
    if filter_type == 'Ram-Lak':
        return np.ones_like(norm_freq)
    elif filter_type == 'Shepp-Logan':
        return np.sinc(norm_freq / (2 * frequency_scaling))
    elif filter_type == 'Cosine':
        return np.cos(norm_freq * np.pi / (2 * frequency_scaling))
    elif filter_type == 'Hamming':
        return 0.54 + 0.46 * np.cos(norm_freq * np.pi / (frequency_scaling))
    elif filter_type == 'Hann':
        return np.cos(norm_freq * np.pi / (2 * frequency_scaling)) ** 2
    else:
        raise ValueError('unknown filter_type')
