using System;
using System.Collections;
using Nequeo.Cryptography.Key.Crypto.Parameters;
using Nequeo.Cryptography.Key.Math;
using Nequeo.Cryptography.Key.Utilities;

namespace Nequeo.Cryptography.Key.Crypto.Engines
{
	/**
	* NaccacheStern Engine. For details on this cipher, see
	* http://www.gemplus.com/smart/rd/publications/pdf/NS98pkcs.pdf
	*/
	public class NaccacheSternEngine
		: IAsymmetricBlockCipher
	{
		private bool forEncryption;
		private NaccacheSternKeyParameters key;
		private IList lookup = null;
		private bool debug = false;
		public string AlgorithmName
		{
			get { return "NaccacheStern"; }
		}

		/**
		 * Initializes the engine. Must be called before all other functions.
		 * @param forEncryption
		 * @param parameters
		 */
		public void Init(
			bool forEncryption,
			ICipherParameters parameters
		)
		{
			forEncryption = forEncryption;
			key = (NaccacheSternKeyParameters)parameters;
			// Construct lookup table for decryption if necessary
			if (!forEncryption)
			{
				IList primes = new List();
				NaccacheSternPrivateKeyParameters priv = (NaccacheSternPrivateKeyParameters)key;
				IList primesList = priv.SmallPrimesList;
				lookup = new List();
				for (int i = 0; i < primesList.Count; i++)
				{
					BigInteger actualPrime = (BigInteger)primesList[i];
					lookup.Add(Platform.CreateArrayList(actualPrime));
				}
			}
		}

		/**
		 * Returns the input block size of the algorithm.
		 * @return input block size
		 */
		public int GetInputBlockSize()
		{
			if (forEncryption)
			{
				// We can only encrypt values up to lowerSigmaBound
				return (key.LowerSigmaBound + 7) / 8 - 1;
			}
			else
			{
				// Pad to modulus size for decryption
				return key.Modulus.BitLength + 1;
			}
		}

		/**
		 * Returns the output block size of the algorithm.
		 * @return output block size
		 */
		public int GetOutputBlockSize()
		{
			if (forEncryption)
			{
				// Output is padded up to modulus size
				return key.Modulus.BitLength + 1;
			}
			else
			{
				// Output is padded up to lowerSigmaBound
				return (key.LowerSigmaBound + 7) / 8 - 1;
			}
		}

		/**
		 * Processes a single block using the Naccache-Stern algorithm.
		 * @param inBytes
		 * @param inOff
		 * @param length
		 * @return output
		 */
		public byte[] ProcessBlock(
			byte[] inBytes,
			int inOff,
			int length
		)
		{
			if (key == null)
				throw new InvalidOperationException("NaccacheStern engine not initialized");

			if (length > GetOutputBlockSize())
				throw new DataLengthException("Input block too large for Naccache-Stern cipher.");

			// Ensure we receive padded data for encryption
			if (forEncryption)
			{
				if (length < GetInputBlockSize())
				{
					throw new InvalidCipherTextException("Block length does not match modulus size for Naccache-Stern cipher.");
				}
			}

			// Convert input to BigInteger
			BigInteger input = new BigInteger(1, inBytes, inOff, length);

			byte[] output;
			if (forEncryption)
			{
				// Encrypt with public key
				output = Encrypt(input);
			}
			else
			{
				// Decrypt with private key
				IList plain = new List();
				NaccacheSternPrivateKeyParameters priv = (NaccacheSternPrivateKeyParameters)key;
				IList primes = priv.SmallPrimesList;
				// Get Chinese Remainder Theorem values
				for (int i = 0; i < primes.Count; i++)
				{
					BigInteger exp = input.ModPow(priv.PhiN.Divide((BigInteger)primes[i]), priv.Modulus);
					IList al = lookup[i];
					if (al.Count != (BigInteger)primes[i].IntValue)
					{
						throw new InvalidCipherTextException("Lookup mismatch for prime " + primes[i]);
					}
					plain.Add(al[exp]);
				}
				// Output is padded with 0s to make it modulus size
				byte[] padded = new byte[key.Modulus.BitLength / 8 + 1];
				for (int i = 0; i < padded.Length; i++)
				{
					padded[i] = (byte)0;
				}
				padded[plain.Count - 1] = (byte)input;
				output = padded;
			}

			return output;
		}

		/**
		 * Encrypts a BigInteger with the public key.
		 * @param plain
		 * @return byte array of encrypted value
		 */
		public byte[] Encrypt(BigInteger plain)
		{
			byte[] output = new byte[key.Modulus.BitLength / 8 + 1];
			byte[] tmp = key.G.ModPow(plain, key.Modulus).ToByteArray();
			Array.Copy(tmp, 0, output, 0, tmp.Length);
			if (debug)
			{
				Console.WriteLine("Encrypted value: " + new BigInteger(output));
			}
			return output;
		}
	}
}
