import org.apache.commons.lang3.builder.HashCodeBuilder;
import org.apache.commons.lang3.builder.ToStringStyle;
import org.apache.commons.lang3.builder.ReflectionToStringBuilder;

public class CmsLinkInfo {
    private String m_anchor;
    private transient int m_hashCode;
    private boolean m_internal;
    private String m_query;
    private CmsUUID m_structureId;
    private String m_target;
    private transient String m_toStringRepr;
    private CmsRelationType m_type;

    public CmsLinkInfo(
        CmsUUID structureId,
        String target,
        String query,
        String anchor,
        CmsRelationType type,
        boolean internal) {
        m_structureId = structureId;
        m_target = target;
        m_query = query;
        m_anchor = anchor;
        m_type = type;
        m_internal = internal;
        HashCodeBuilder hashCodeBuilder = new HashCodeBuilder();
        hashCodeBuilder.append(m_structureId);
        hashCodeBuilder.append(m_target);
        hashCodeBuilder.append(m_query);
        hashCodeBuilder.append(m_anchor);
        hashCodeBuilder.append(m_internal);
        m_hashCode = hashCodeBuilder.toHashCode();
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null) return false;
        if (getClass() != obj.getClass()) return false;
        CmsLinkInfo other = (CmsLinkInfo) obj;
        if (m_anchor == null) {
            if (other.m_anchor != null) return false;
        } else if (!m_anchor.equals(other.m_anchor)) return false;
        if (m_internal != other.m_internal) return false;
        if (m_query == null) {
            if (other.m_query != null) return false;
        } else if (!m_query.equals(other.m_query)) return false;
        if (m_structureId == null) {
            if (other.m_structureId != null) return false;
        } else if (!m_structureId.equals(other.m_structureId)) return false;
        if (m_target == null) {
            if (other.m_target != null) return false;
        } else if (!m_target.equals(other.m_target)) return false;
        return true;
    }

    @Override
    public int hashCode() {
        return m_hashCode;
    }

    public String getAnchor() {
        return m_anchor;
    }

    public String getQuery() {
        return m_query;
    }

    public CmsUUID getStructureId() {
        return m_structureId;
    }

    public String getTarget() {
        return m_target;
    }

    public CmsRelationType getType() {
        return m_type;
    }

    public boolean isInternal() {
        return m_internal;
    }

    public CmsLink toLink() {
        return new CmsLink(
            m_structureId,
            m_target,
            m_query,
            m_anchor,
            m_type,
            m_internal
        );
    }
}
