        {
            if (_folderInvalidateTimer != null)
            {
                _folderInvalidateTimer.Stop();
                _folderInvalidateTimer.Dispose();
            }

            // Unsubscribe from events
            _folderSystem.Folders.ItemAdded -= FolderItemAdded;
            _folderSystem.Folders.ItemRemoved -= FolderItemRemoved;
            _folderSystem.Folders.Changed -= FoldersChanged;
            _folderSystem.FoldersInvalidated -= FoldersInvalidated;
            _folderSystem.FolderPropertiesChanged -= FolderPropertiesChanged;

            base.Stop();
        }

        private void Initialize()
        {
            _initializationState = InitializationState.NotInitialized;

            // Initialize the folder system
