using UnityEngine;
using System.Collections.Generic;

namespace Mixamo {

public interface TransitionHandler {
    string[] KeyControls();
    bool CanTransitionTo(string guard, string source, string destination);
}

public class ControlParameters {
    Dictionary<string, float> dict = new Dictionary<string, float>();

    public ControlParameters(string[] opts, float[] vals) {
        if (opts != null && vals != null) {
            for (int i = 0; i < opts.Length; i++) {
                dict.Add(opts[i], vals[i]);
            }
        }
    }

    public string[] Names {
        get {
            string[] arr = new string[dict.Keys.Count];
            dict.Keys.CopyTo(arr, 0);
            return arr;
        }
    }
}

public class Transition {
    public bool WaitTillEnd = false;
    protected State destination;
    protected State _start_destination = null;
    protected string[] guards = null;
    protected State source;
    protected bool finished = true;

    public Transition() {
        source = new State();
        destination = new State();
        start_destination = source;
    }

    public void Start(State dest) {
        finished = false;
        destination = dest;
        if (!dest.IsLooping) {
            destination.ResetTime(0f);
        }
    }

    public void Finish() {
        finished = true;
    }

    public bool CanTransitionTo(State dest) {
        if (guards != null) {
            foreach (string g in guards) {
                if (handler.CanTransitionTo(g, source.name, dest.name)) {
                    return true;
                }
            }
        }
        return (dest == start_destination && finished);
    }

    public override string ToString() {
        return string.Format("Transition: Source={0}, Destination={1}", source.name, destination.name);
    }
}

public class CrossfadeTransition : Transition {
    public CrossfadeTransition(State source, State destination, float duration) {
        this.source = source;
        this.destination = destination;
        this.duration = duration;
    }

    public override void Start(State dest) {
        base.Start(dest);
        duration = 0f;
    }

    public override void UpdateGraph(float remaining_weight) {
        if (WaitTillEnd && (source.NormalizedTime < 1f)) {
            source.UpdateGraph(remaining_weight);
            destination.UpdateGraph(0f);
            destination.ResetTime(0f);
        } else {
            float t = Mixamo.Util.CrossFadeUp(t_weight, duration);
            source.UpdateGraph((1 - t) * remaining_weight);
            destination.UpdateGraph(t * remaining_weight);
            destination.ResetTime(0f);
        }
    }
}

public class ClipTransition : Transition {
    public ClipTransition(State source, State destination, float duration, Clip clip) {
        this.source = source;
        this.destination = destination;
        this.duration = duration;
        this.clip = clip;
    }

    public override void Start(State dest) {
        base.Start(dest);
        duration = 0f;
    }

    public override void UpdateGraph(float remaining_weight) {
        if (WaitTillEnd && (source.NormalizedTime < 1f)) {
            source.UpdateGraph(remaining_weight);
            destination.UpdateGraph(0f);
            destination.ResetTime(0f);
        } else {
            float t = Mixamo.Util.CrossFadeUp(t_weight, duration);
            source.UpdateGraph((1 - t) * remaining_weight);
            destination.UpdateGraph(t * remaining_weight);
            destination.ResetTime(0f);
        }
    }
}
