using System;
using System.Collections.Generic;
using System.Text;
using System.Xml;

namespace RuleEngine
{
    public class ROM : ICloneable
    {
        #region instance variables
        private Dictionary<string, IEvidence> evidenceCollection = new Dictionary<string, IEvidence>();
        private Dictionary<string, XmlDocument> models = new Dictionary<string, XmlDocument>();
        private Dictionary<string, List<string>> dependentEvidence = new Dictionary<string, List<string>>();
        private Dictionary<string, Delegate> callback = new Dictionary<string, Delegate>();
        #endregion

        #region constructor
        public ROM()
        {
        }
        #endregion

        #region core
        public void AddModel(string modelId, XmlDocument model)
        {
            models[modelId] = model;
        }

        public void AddEvidence(IEvidence evidence)
        {
            evidenceCollection[evidence.ID] = evidence;
        }

        public void AddDependentFact(string evidence, string dependentEvidence)
        {
            if (!dependentEvidence.Contains(evidence))
                dependentEvidence.Add(evidence);
            dependentEvidence[evidence] = new List<string> { dependentEvidence };
        }

        public IEvidence this[string id]
        {
            get
            {
                if (evidenceCollection.ContainsKey(id))
                {
                    return evidenceCollection[id];
                }
                return null;
            }
        }

        public void Evaluate()
        {
            Decisions.Decision decision = new Decisions.Decision();
            decision.EvidenceLookup += evidence_EvidenceLookup;
            decision.ModelLookup += evidence_ModelLookup;
            decision.Evaluate(evidenceCollection, dependentEvidence);
        }

        public IEvidence Clone()
        {
            ROM clone = new ROM();
            clone.callback = new Dictionary<string, Delegate>(this.callback);
            clone.dependentEvidence = new Dictionary<string, List<string>>(this.dependentEvidence);
            clone.evidenceCollection = new Dictionary<string, IEvidence>(this.evidenceCollection);
            return clone;
        }

        public void RegisterCallback(string name, Delegate callback)
        {
            callback = new Delegate(callback);
            callback.Name = name;
            callback.Delegate = callback;
        }

        private void evidence_EvidenceLookup(object sender, EvidenceLookupArgs args)
        {
            IEvidence evidence = evidenceCollection[args.Key];
            if (evidence != null)
            {
                evidence.EvidenceLookup += evidence_EvidenceLookup;
            }
        }

        private void evidence_ModelLookup(object sender, ModelLookupArgs args)
        {
            XmlDocument model = models[args.Key];
            if (model != null)
            {
                model.ModelLookup += evidence_ModelLookup;
            }
        }
        #endregion

        #region ICloneable
        public object Clone()
        {
            return new ROM();
        }
        #endregion
    }
}
