            self.packets = self.sniffer_packets(iface, filter_, 1)

        return self.packets

    def sniffer_packets(self, iface, filter_, num_packets):
        packets = []
        for i in range(num_packets):
            packet = sniff(iface, filter=filter_, prn=self.statement)
            packets.append(packet)
        return packets

    def main(self, customArgs=None):
        if customArgs is None:
            args = self.arguments()
        else:
            args = self.arguments(customArgs)

        if not args:
            return

        iface = args.iface
        filter_ = args.filter
        num_packets = args.num

        if num_packets is not None:
            self.packets = self.sniffer(iface, filter_, num_packets)
        else:
            self.packets = self.sniffer(iface, filter_, 1)

        if self.packets:
            self.write_packets(self.packets)
        else:
            print(self.red + "No packets captured" + self.blk)

    def write_packets(self, packets):
        for packet in packets:
            print(self.green + str(packet.summary()) + self.blk)

