class MachCommands(CommandBase):
    @Command('build', description='Build Servo', category='build')
    @CommandArgument('--target', '-t', default=None, help='Cross compile for given target platform')
    @CommandArgument('--release', '-r', action='store_true', help='Build in release mode')
    @CommandArgument('--dev', '-d', action='store_true', help='Build in development mode')
    @CommandArgument('--jobs', '-j', default=None, help='Number of jobs to run in parallel')
    @CommandArgument('--android', action='store_true', help='Build for Android')
    @CommandArgument('--debug-mozjs', action='store_true', help='Enable debug assertions in mozjs')
    @CommandArgument('--verbose', action='store_true', help='Print verbose output')
    @CommandArgument('params', nargs='*')
    def build(self, target=None, release=False, dev=False, jobs=None, android=None, verbose=False, debug_mozjs=False, params=None):
        if android is None:
            android = self.config['build']['android']
        opts = params or []
        features = []
        base_dir = self.get_target_dir()
        release_dir = path.join(base_dir, "release", "servo")
        dev_dir = path.join(base_dir, "debug", "servo")
        release_exists = os.path.exists(release_dir)
        dev_exists = os.path.exists(dev_dir)
        if not (release_exists and dev_exists):
            if dev:
                dev = True
            elif release_exists:
                release = True
            else:
                release = False
            if release and dev:
                print("Please specify either --dev or --release.")
                sys.exit(1)
        if release and dev:
            print("Please specify either --dev or --release.")
            sys.exit(1)
        self.ensure_bootstrapped()
        if release:
            opts.append("--release")
        if target:
            opts.append("--target", target)
        if jobs is not None:
            opts.append("-j", jobs)
        if verbose:
            opts.append("-v")
        if android:
            # Ensure the APK builder submodule has been built
            apk_dir = path.join("support", "android-rs-glue")
            with cd(apk_dir):
                status = call(["cargo", "build"], env=self.build_env())
                if status:
                    print("Build failed:", status)
                    sys.exit(1)
        if debug_mozjs:
            features.append("script/debugmozjs")
        if is_headless_build():
            opts.append("--no-default-features")
            features.append("headless")
        if android:
            features.append("android-glue")
        if features:
            opts.append("--features", " ".join(features))
        start_time = time()
        env = self.build_env()
        status = call(["cargo", "build"], env=env, verbose=verbose)
        if status:
            print(f"Build started at {start_time}")
            print("Build complete in {time() - start_time:.2f} seconds")
            print("Build status: %s" % status)
            sys.exit(0)
