using System;
using System.Collections;
using System.ComponentModel;
using System.Windows.Forms;
using System.Security.Cryptography;
using System.Text;
using System.Web.Services.Protocols;
using System.Web.Services;
using System.Diagnostics;
using System.Xml.Serialization;

namespace OpenLink.Virtuoso.WSS.AsymmetricEncryption
{
    /// <summary>
    /// This is a sample which allows the user to send
    /// a message encrypted with an RSA and triple-des keys.
    /// </summary>
    public class AddClient
    {
        int a, b;
        string url;

        AddClient(string[] args)
        {
            Hashtable arguments = new Hashtable();
            ParseArguments(args, ref arguments);
            if (arguments.Contains("?"))
            {
                Usage();
            }
            try
            {
                ConvertArgument(arguments, "a", ref a);
                ConvertArgument(arguments, "b", ref b);
                url = (string)arguments["url"];
            }
            catch (Exception)
            {
                Usage();
                throw;
            }
        }

        static void Main(string[] args)
        {
            AddClient client = new AddClient(args);
            client.Run();
        }

        void Run()
        {
            CallWebService(a, b, url);
        }

        void Usage()
        {
            Console.WriteLine("Usage: AsymmetricEncryptionClient /a /b");
            Console.WriteLine(" Required arguments:");
            Console.WriteLine("    /url The Secure service endpoint");
            Console.WriteLine("    /a An integer. First number to add.");
            Console.WriteLine("    /b An integer. Second number to add.");
        }

        protected void ConvertArgument(Hashtable args, string argName, ref int arg)
        {
            if (!args.Contains(argName))
            {
                throw new ArgumentException(argName);
            }
            arg = int.Parse(args[argName] as string);
        }

        protected void ConvertArgument(Hashtable args, string argName, ref long arg)
        {
            if (!args.Contains(argName))
            {
                throw new ArgumentException(argName);
            }
            arg = long.Parse(args[argName] as string);
        }

        protected void ConvertArgument(Hashtable args, string argName, ref bool arg)
        {
            if (!args.Contains(argName))
            {
                throw new ArgumentException(argName);
            }
            arg = bool.Parse(args[argName] as string);
        }

        protected string GetOption(string arg)
        {
            if (!arg.StartsWith("/") && !arg.StartsWith("-"))
                return null;
            return arg;
        }

        protected void ParseArguments(string[] args, ref Hashtable table)
        {
            int index = 0;
            while (index < args.Length)
            {
                string option = GetOption(args[index]);
                if (option != null)
                {
                    table[option] = args[++index];
                }
                index++;
            }
        }

        protected void CallWebService(int a, int b, string url)
        {
            // Instantiate an instance of the web service proxy
            AddNumbersProxy proxy = new AddNumbersProxy();
            SoapContext context = proxy.RequestSoapContext();

            // Get the Asymmetric key
            X509SecurityToken token = GetEncryptionToken();
            if (token == null)
                throw new ApplicationException("No security token provided.");

            // Add an EncryptedData element to the security collection
            context.Security.Elements.Add(new EncryptedData(token));

            // Set the URL for the web service
            if (url != null)
            {
                proxy.Url = url;
            }

            // Call the service
            int result = proxy.AddInt(a, b);
            Console.WriteLine($"Service returned: {result}");
        }

        protected X509SecurityToken GetEncryptionToken()
        {
            X509SecurityToken token = null;
            // Certificate store
            X509CertificateStore store = X509CertificateStore.CurrentUserStore();
            bool open = store.OpenRead();
            try
            {
                // Dialog to select certificate
                StoreDialog dialog = new StoreDialog(store);
                X509Certificate cert = dialog.SelectCertificate();
                if (cert == null)
                {
                    throw new ApplicationException("No certificate selected.");
                }
                else if (!cert.SupportsDataEncryption)
                {
                    throw new ApplicationException("Certificate does not support key encipherment.");
                }
                else
                {
                    token = new X509SecurityToken(cert);
                }
            }
            finally
            {
                if (store != null)
                {
                    store.Close();
                }
            }
            return token;
        }

        protected class StoreDialog
        {
            X509CertificateStore store;
            public StoreDialog(X509CertificateStore store)
            {
                this.store = store;
            }

            public X509Certificate SelectCertificate()
            {
                if (store == null)
                    throw new Exception("Store is not open.");
                if (store.Handle == IntPtr.Zero)
                    throw new Exception("Store not open.");
                IntPtr certHandle = CryptUIDlgSelectCertificateFromStore(store.Handle, 0, 0, 0, 0, 0, 0);
                if (certHandle != IntPtr.Zero)
                {
                    return new X509Certificate(certHandle);
                }
                return null;
            }
        }

        protected class AddNumbersProxy
        {
            public string Url { get; set; }
            public int AddInt(int a, int b)
            {
                SoapContext context = new SoapContext();
                context.RequestNamespace = "http://temp.uri/";
                context.ResponseNamespace = "http://temp.uri/";
                return context.Invoke("AddInt", new object[] { a, b });
            }
        }

        protected class EncryptedData
        {
            X509SecurityToken token;
            public EncryptedData(X509SecurityToken token)
            {
                this.token = token;
            }
        }
    }
}
