        private void ConnectClick(object sender, RoutedEventArgs e)
        {
            var pwd = PwdBox.Password;
            if (!IsConnected)
            {
                var settings = Properties.Settings.Default;
                if (settings.Username.IsNullOrEmpty())
                {
                    MessageBox.Show(this, LocalizedStrings.Str3751, MessageBoxButton.OK, MessageBoxImage.Error);
                    return;
                }
                if (pwd.IsNullOrEmpty())
                {
                    MessageBox.Show(this, LocalizedStrings.Str2975, MessageBoxButton.OK, MessageBoxImage.Error);
                    return;
                }
                if (Trader == null)
                {
                    Trader = new RithmicTrader { LogLevel = LogLevels.Debug };
                    _logManager.Sources.Add(Trader);
                    Trader.Connected += () => OnConnectionChanged();
                    Trader.ConnectionError += (error) => OnConnectionChanged(Trader.ConnectionState == ConnectionStates.Connected);
                    Trader.Disconnected += () => OnConnectionChanged(false);
                    Trader.Error += (error) => OnConnectionChanged(Trader.ConnectionState == ConnectionStates.Connected);
                    Trader.MarketDataSubscriptionFailed += (security, type, error) => OnMarketDataSubscriptionFailed(error);
                    Trader.NewSecurities += securities => _securitiesWindow.SecurityPicker.Securities.AddRange(securities);
                    Trader.NewOrders += orders => _ordersWindow.OrderGrid.Orders.AddRange(orders);
                    Trader.NewPositions += positions => _portfoliosWindow.PortfolioGrid.Positions.AddRange(positions);
                    Trader.NewStopOrders += orders => _stopOrdersWindow.OrderGrid.Orders.AddRange(orders);
                    Trader.NewMyTrades += trades => _myTradesWindow.TradeGrid.Trades.AddRange(trades);
                }
                Trader.UserName = settings.Username;
                Trader.Server = settings.Server;
                Trader.Password = pwd;
                Trader.CertFile = settings.CertFile;
                Trader.Connect();
            }
        }

        private void OnConnectionChanged(bool isConnected)
        {
            IsConnected = isConnected;
            ConnectBtn.Content = isConnected ? LocalizedStrings.Disconnect : LocalizedStrings.Connect;
        }

